with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , coalesce(nullif(trim(COVER_SECTION), ''), '') as COVER_SECTION_CODE
        , 'ICU' as WARD_CLASS_CODE
        , HOSP_TOT_ICU_DAYS as TOTAL_DAYS
        , HOSP_BAL_ICU_DAYS as BALANCE_DAYS
        , HOSP_ELGI_AMT_ICU as ELIGIBLE_AMOUNT_PER_DAY
        , HOSP_ICU as ASSESSED_COMPONENT_VALUE
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        COVER_SECTION_CODE,
        WARD_CLASS_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then TOTAL_DAYS end) as TOTAL_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then BALANCE_DAYS end) as BALANCE_DAYS,
        max(case when SOURCE_RUN = 'opus_health_v2' then ELIGIBLE_AMOUNT_PER_DAY end) as ELIGIBLE_AMOUNT_PER_DAY,
        max(case when SOURCE_RUN = 'opus_health_v2' then ASSESSED_COMPONENT_VALUE end) as ASSESSED_COMPONENT_VALUE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK, COVER_SECTION_CODE, WARD_CLASS_CODE
),

hashed as (
    select
        *,
        case when COVER_SECTION_CODE is not null or WARD_CLASS_CODE is not null or TOTAL_DAYS is not null or BALANCE_DAYS is not null or ELIGIBLE_AMOUNT_PER_DAY is not null or ASSESSED_COMPONENT_VALUE is not null
                     then md5(upper(coalesce(cast(COVER_SECTION_CODE as varchar), '') || '|' || coalesce(cast(WARD_CLASS_CODE as varchar), '') || '|' || coalesce(cast(TOTAL_DAYS as varchar), '') || '|' || coalesce(cast(BALANCE_DAYS as varchar), '') || '|' || coalesce(cast(ELIGIBLE_AMOUNT_PER_DAY as varchar), '') || '|' || coalesce(cast(ASSESSED_COMPONENT_VALUE as varchar), '')))
                end as SAT_CLAIM_HOSPITAL_DAY_LIMIT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_HOSPITAL_DAY_LIMIT_HASHDIFF is not null
